      "desc": "毛泽东的夫人，早年投身文艺与进步事业，三十年代活跃于上海影剧界。文化大革命时期任中央文革小组副组长、中共中央政治局委员，是当时文艺与政治领域的重要人物，参与并推动了京剧革命与现代戏（「革命样板戏」）的整理推广。1976 年 10 月被隔离审查，1981 年经特别法庭审判被认定为「林彪、江青反革命集团」案主犯——此为官方定性；而不少马列毛主义者则肯定其在文化革命中的工作与革命立场，主张联系当时的路线斗争重新评价其历史功过。",
