      "desc": "俄国马克思主义的奠基人。1856 年生于坦波夫省，早年参加民粹派「土地与自由社」，1880 年流亡国外后同民粹主义决裂。1883 年在日内瓦创立劳动解放社，组织翻译《共产党宣言》等著作，把马克思主义传入俄国，并著《我们的意见分歧》《论一元论历史观的发展》批判民粹派的历史观。1900 年参与创办《火星报》。1903 年俄国社会民主工党第二次代表大会后转向孟什维克，反对列宁的建党原则。第一次世界大战期间持护国主义立场，1917 年反对十月武装起义，认为俄国尚不具备社会主义革命的条件。1918 年病逝于芬兰。",
