      "desc": "布尔什维克党和共产国际的领导人之一，马克思主义理论家。1906 年加入俄国社会民主工党，多次被捕流亡。1917 年起为中央委员，长期主编《真理报》，1924 年起为政治局委员。著有《共产主义 ABC》《过渡时期经济学》《历史唯物主义理论》等。新经济政策时期主张通过市场关系和国家调节引导农民，反对用行政手段强制集体化。1926 至 1929 年实际主持共产国际工作。1929 年被批判为「右倾反对派」并撤销领导职务。1938 年在莫斯科审判中被处死刑，1988 年苏联最高法院为其平反。列宁曾称他是党内「最可贵和最大的理论家」，同时指出他在辩证法问题上不够彻底。",
