      "role": "德国工人哲学家 · 辩证唯物主义通俗化者",
      "desc": "德国制革工人出身的哲学家，自学成才。参加过 1848 年革命，后流亡美国、俄国，长期以制革为业，同时独立研究哲学。1867 年把《人脑活动的本质》手稿寄给马克思，马克思予以肯定并向恩格斯推荐。他试图用通俗语言阐明物质第一性、意识是大脑的产物、世界可知等原理，被列宁称为「自己摸索出辩证唯物主义」的人。但其表述有混乱之处，恩格斯曾指出他缺乏辩证法的训练，后来马赫主义者又利用这些缺陷把他说成同唯心主义相容的哲学家。主要著作还有《一个社会主义者在认识论领域中的漫游》《哲学的成果》。1888 年病逝于美国芝加哥。",
