      "desc": "德国工人运动活动家、马克思主义史学家和政论家。早年任民主派记者，1891 年加入德国社会民主党后主编党的理论刊物《新时代》和《莱比锡人民报》，系统批判伯恩施坦修正主义。所著《莱辛传奇》得到恩格斯好评，《德国社会民主党史》《卡尔·马克思传》为早期马克思主义史学的重要著作。第一次世界大战期间反对战争拨款，参加斯巴达克同盟，1918 年底参与创建德国共产党。其史学著作对德国工人运动史研究影响很大。1919 年病逝于柏林。",
