      "role": "意大利马克思主义理论家 · 历史唯物主义阐释者",
      "desc": "意大利马克思主义理论家、罗马大学教授。早年研究黑格尔和赫尔巴特哲学，后转向社会主义，1890 年代系统研读马克思、恩格斯著作并与恩格斯保持通信。著有《纪念〈共产党宣言〉》《关于历史唯物主义》《关于社会主义与哲学的谈话》，主张把历史唯物主义理解为解释历史的总的方法而不是现成的公式，强调意识形态、道德和传统在社会发展中的相对独立作用，反对把唯物史观简单化为经济决定论。他反对伯恩施坦修正主义，同时也批评意大利社会党内的教条主义。其思想对葛兰西有直接影响。1904 年病逝于罗马。",
